import asyncio

from contract import EmbedPostingsInput, EmbedPostingsOutput, EmbedPostingsCaps
from clean_text.contract import CleanTextInput
from clean_text.impl import clean_text
from embed_text.contract import EmbedTextInput
from embed_text.impl import embed_text


async def embed_postings(value: EmbedPostingsInput, caps: EmbedPostingsCaps) -> EmbedPostingsOutput:
    """Turn job postings into vectors so they can be compared by similarity."""
    postings = value.postings
    model_name = value.model_name

    clean_text_results = await asyncio.gather(*(clean_text(CleanTextInput(posting=posting), caps) for posting in postings))
    text = [result.text for result in clean_text_results]

    embed_text_results = await asyncio.gather(*(embed_text(EmbedTextInput(text=text_item, model_name=model_name), caps) for text_item in text))
    vector = [result.vector for result in embed_text_results]

    return EmbedPostingsOutput(vectors=vector)
